"use strict";(self.webpackChunkdocsite=self.webpackChunkdocsite||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/blog/welcome","editUrl":"https://github.com/LDubya/OpenKeyNav_Dev/tree/main/blog/2024-08-13-welcome.md","source":"@site/blog/2024-08-13-welcome.md","title":"Welcome","description":"OpenKeyNav is an open-source JavaScript library that adds on-demand keyboard operation and navigation modes to websites and web apps.","date":"2024-08-13T00:00:00.000Z","tags":[{"inline":false,"label":"Basics","permalink":"/blog/tags/basics","description":"Introductions and practical OpenKeyNav fundamentals"}],"readingTime":1.25,"hasTruncateMarker":false,"authors":[{"name":"The OpenKeyNav Team"}],"frontMatter":{"slug":"welcome","title":"Welcome","authors":{"name":"The OpenKeyNav Team"},"tags":["basics"]},"unlisted":false},"content":"OpenKeyNav is an open-source JavaScript library that adds on-demand keyboard operation and navigation modes to websites and web apps.\\n\\n## Why OpenKeyNav?\\n\\nPeople use keyboard interfaces through physical keyboards, switches, voice input, screen readers, and other assistive technologies. Web teams need repeatable ways to provide direct keyboard action, navigation, and movement across the experiences they build.\\n\\nOpenKeyNav provides that shared interaction layer:\\n\\n- **Click Mode** labels detected targets for direct focus or activation.\\n- **Move Mode** maps application-defined sources and destinations to a keyboard workflow.\\n- **Navigation commands** create direct routes through headings, scrollable regions, and page structure.\\n- **Configurable commands** give applications one place to manage activation, interaction, movement, and exit keys.\\n- **Focused diagnostics** identify actions for manual review of semantics, focus, activation, and task completion.\\n\\n## Keyboard accessibility standards\\n\\nWCAG 2.1.1 requires all functionality to be operable through a keyboard interface. OpenKeyNav provides reusable keyboard paths for detected targets and configured workflows. Teams verify those paths across each required action, state change, and outcome in the complete task.\\n\\nThe [ADA Title II keyboard accessibility guide](https://openkeynav.com/docs/ada-title-ii-keyboard-accessibility) connects this implementation work to the federal WCAG 2.1 Level AA timeline for state and local governments.\\n\\n## Getting started\\n\\nFollow the [Quick Start Guide](https://openkeynav.com/docs/getting_started/quick_start_guide) to install OpenKeyNav, exercise Click Mode, verify detected actions, and configure specialized workflows.\\n\\n## Research and development\\n\\nOpenKeyNav grows through implementation work, accessibility research, adopter feedback, and evaluation with disabled users. Share implementation questions, reproducible issues, and documentation feedback through the [OpenKeyNav GitHub repository](https://github.com/LDubya/OpenKeyNav).\\n\\n**The OpenKeyNav Team**"}]}}')}}]);